import React, { useState, useEffect } from 'react';
import { getAssociatedFranchises } from '../services/api';

const ExamDataUser = () => {
  const [examDataList, setExamDataList] = useState([]);

  useEffect(() => {
    const fetchExamData = async () => {
      try {
        const franchises = await getAssociatedFranchises();
        if (franchises.length > 0) {
          setExamDataList(franchises[0].examData || []);
        } else {
          setExamDataList([]);
        }
      } catch (error) {
        console.error('Error fetching exam data:', error);
        alert('Unable to retrieve exam data. Please try again later.');
      }
    };

    fetchExamData();
  }, []);

  return (
    <div style={styles.container}>
      <h1 style={styles.header}>Exam Data</h1>

      {/* Table to display exam data */}
      {examDataList.length > 0 ? (
        <div style={styles.tableContainer}>
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={styles.th}>Exam Name</th>
                <th style={styles.th}>Date</th>
                <th style={styles.th}>Duration (Minutes)</th>
                <th style={styles.th}>Status</th>
              </tr>
            </thead>
            <tbody>
              {examDataList.map((exam, index) => (
                <tr key={index} style={styles.tr}>
                  <td style={styles.td}>{exam.examName}</td>
                  <td style={styles.td}>
                    {new Date(exam.date).toLocaleDateString()}
                  </td>
                  <td style={styles.td}>{exam.durationInMinutes}</td>
                  <td style={styles.td}>{exam.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <p style={styles.noData}>No exam data available for your franchise.</p>
      )}
    </div>
  );
};

// CSS styles in JS format
const styles = {
  container: {
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
  },
  header: {
    fontSize: '2rem',
    textAlign: 'center',
    marginBottom: '20px',
  },
  tableContainer: {
    overflowX: 'auto', // Ensures table is scrollable on small screens
    marginTop: '20px',
  },
  table: {
    width: '100%',
    borderCollapse: 'collapse',
    tableLayout: 'fixed',
    marginBottom: '20px',
  },
  th: {
    padding: '12px',
    backgroundColor: '#007bff',
    color: 'white',
    textAlign: 'left',
    border: '1px solid #ddd',
  },
  td: {
    padding: '12px',
    textAlign: 'left',
    border: '1px solid #ddd',
  },
  tr: {
    transition: 'background-color 0.3s ease',
  },
  trHover: {
    backgroundColor: '#f1f1f1',
  },
  noData: {
    textAlign: 'center',
    padding: '20px',
    color: '#888',
  },
};

export default ExamDataUser;
